$ node demo.mjs
GET /early                         200  {"note":"registered BEFORE the header middleware"}   [x-served-by: null]
GET /users/42?verbose=1            200  {"id":"42","query":{"verbose":"1"}}   [x-served-by: mini-express]
POST /users {name}                 201  {"created":"Ada"}   [x-served-by: mini-express]
POST /users {} (validation)        422  {"error":"name is required"}   [x-served-by: mini-express]
